using System;
using System.Collections.Generic;

namespace Astrea;

public class OrionOmensHandler : ReferenceSingleton<OrionOmensHandler>
{
	[NonSerialized]
	public List<Action> AstriumActivatedOmenActions = new List<Action>();

	[NonSerialized]
	public bool CrystallizedMemoryOmenActive;

	[NonSerialized]
	public Func<int, int> PlatinumStarOmenAction;

	[NonSerialized]
	public Func<int, int> PlatinumStarDevotionOmenAction;

	[NonSerialized]
	public Action ShootingStarOmenAction;

	[NonSerialized]
	public Action ShootingStarOmenFeedbackAction;

	[NonSerialized]
	public Action MirrorOfThoughtOmenAction;

	[NonSerialized]
	public Action OnDeactivatingKarmicOrbMirrorOfThoughtOmenAction;

	[NonSerialized]
	public Action HeartFragmentMovingAction;

	[NonSerialized]
	public Action HeartFragmentStartOfBattleAction;

	[NonSerialized]
	public Func<int, int> GravitationalReagentOmenAction;

	[NonSerialized]
	public Action ConstellationBeadsOmenAction;

	public void ActivateAstriumActivatedOmens()
	{
		for (int i = 0; i < AstriumActivatedOmenActions.Count; i++)
		{
			AstriumActivatedOmenActions[i]();
		}
	}

	public void OnActivateShootingStarOmen()
	{
		ShootingStarOmenAction?.Invoke();
	}

	public bool IsShootingStarOmenActive(bool activateFeedback)
	{
		bool num = ShootingStarOmenAction != null;
		if (num && activateFeedback)
		{
			ShootingStarOmenFeedbackAction();
		}
		return num;
	}

	public void OnActivateMirrorOfThoughtOmen()
	{
		MirrorOfThoughtOmenAction?.Invoke();
	}

	public void OnDeactivatingKarmicOrbActivateMirrorOfThoughtOmen()
	{
		OnDeactivatingKarmicOrbMirrorOfThoughtOmenAction?.Invoke();
	}

	public void ActivateHeartFragmentMovingOmen()
	{
		HeartFragmentMovingAction?.Invoke();
	}

	public bool IsHeartFragmentActiveAndActivateStartOfBattle()
	{
		bool num = HeartFragmentStartOfBattleAction != null;
		if (num)
		{
			HeartFragmentStartOfBattleAction();
		}
		return num;
	}
}
